create table if not exists annual_plans (id uuid primary key, classroom_id uuid not null references classrooms(id), school_year_id uuid not null references school_years(id), curriculum_version_id uuid not null references curriculum_versions(id), diagnostic_session_id uuid references diagnostic_sessions(id), version integer not null default 1, status text not null default 'draft' check (status in ('draft','active','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), teacher_confirmed_at timestamptz, unique(classroom_id, school_year_id, version));
create table if not exists annual_plan_competencies (id uuid primary key, plan_id uuid not null references annual_plans(id), competency_id uuid not null references competencies(id), planning_emphasis text not null default 'usual' check (planning_emphasis in ('usual','consider','prioritize')), rationale text, teacher_confirmed boolean not null default false, unique(plan_id, competency_id));
create table if not exists annual_plan_changes (id uuid primary key, plan_id uuid not null references annual_plans(id), change_type text not null check (change_type in ('interest_emerged','observed_need','context_change','institutional_reschedule','other')), reason text not null, previous_payload jsonb not null default '{}'::jsonb, new_payload jsonb not null default '{}'::jsonb, confirmed_by_teacher boolean not null default false, changed_at timestamptz not null default now());
alter table learning_experiences add column if not exists annual_plan_id uuid references annual_plans(id), add column if not exists origin text not null default 'planned' check (origin in ('planned','emergent')), add column if not exists planning_reason text;
